// A cluster of quartz points: a few thick six-sided sticks with
// pyramid tips, one tall tower and smaller ones around it.
// Units: mm.

const n_tau = PI * 2;
const n_height = 150;
// One layer per mm, so the edge under each tip falls on a layer.
const n_its_layer = 150;
// Many corners, so the sticks' edges stay sharp.
const n_its_corner = 777;
const n_height_cone = 6;
// No dome: the tower ends in a point on its own.
const n_height_dome = 0;
const n_overhang_dome = 60;

// Another number cuts the facets differently.
const n_seed = 2;
// How uneven the six sides of a stick are: 0 is a regular hexagon.
const n_uneven = 0.14;
// How far a tip may sit off its stick's middle, as a share of the
// stick's radius.
const n_tip_off = 0.25;

// The sticks. The first is the tower: all others must end below
// where its tip starts (n_h - n_tip), and it must stay first.
//   n_x, n_y   where it stands, seen from above
//   n_radius   from its middle to its sides
//   n_h        how high its tip reaches
//   n_tip      how long its pyramid is. Shorter than about
//              n_radius leans too flat to print.
//   n_turn     how far it is turned, in degrees
const a_o_stick = [
    { n_x: 0, n_y: 4, n_radius: 16, n_h: 152, n_tip: 26, n_turn: 12 },
    { n_x: 19, n_y: -3, n_radius: 12, n_h: 104, n_tip: 17, n_turn: 40 },
    { n_x: -19, n_y: 1, n_radius: 11.5, n_h: 84, n_tip: 16, n_turn: 5 },
    { n_x: 13, n_y: 21, n_radius: 10.5, n_h: 92, n_tip: 15, n_turn: 25 },
    { n_x: -15, n_y: 20, n_radius: 10, n_h: 66, n_tip: 14, n_turn: 50 },
    { n_x: 17, n_y: -20, n_radius: 10, n_h: 70, n_tip: 14, n_turn: 18 },
    { n_x: -9, n_y: -22, n_radius: 9, n_h: 47, n_tip: 12, n_turn: 33 },
    { n_x: 5, n_y: -26, n_radius: 8.5, n_h: 42, n_tip: 12, n_turn: 8 },
    { n_x: -23, n_y: -11, n_radius: 9, n_h: 58, n_tip: 12, n_turn: 44 },
];

// A fixed random number from 0 to 1 for each n.
function f_n_rand(n) {
    return fract(sin(n * 127.1 + n_seed * 311.7) * 43758.5453);
}

// Prepare each stick once: its six sides, each with a direction
// (n_nx, n_ny) and a distance from the tip's place, and the place
// of its tip (n_x_tip, n_y_tip).
for (let n_it = 0; n_it < a_o_stick.length; n_it++) {
    const o = a_o_stick[n_it];
    // The tower's tip stays in its middle: the whole shape is
    // measured from there.
    const n_off = n_it == 0 ? 0 : o.n_radius * n_tip_off * f_n_rand(n_it * 10 + 7);
    const n_angle_off = f_n_rand(n_it * 10 + 8) * n_tau;
    o.n_x_tip = o.n_x + sin(n_angle_off) * n_off;
    o.n_y_tip = o.n_y + cos(n_angle_off) * n_off;
    o.a_o_side = [];
    for (let n_side = 0; n_side < 6; n_side++) {
        const n_angle = (o.n_turn / 360 + n_side / 6) * n_tau;
        const n_nx = sin(n_angle);
        const n_ny = cos(n_angle);
        const n_dist = o.n_radius
            * (1 + (f_n_rand(n_it * 10 + n_side) - 0.5) * 2 * n_uneven);
        o.a_o_side.push({
            n_nx, n_ny,
            // From the tip's place to this side.
            n_dist: n_dist - (n_nx * (o.n_x_tip - o.n_x) + n_ny * (o.n_y_tip - o.n_y)),
        });
    }
}

// Every corner looks outward from the tower's middle, not from the
// lamp's axis, so the tower can stand off the axis.
const n_x_eye = a_o_stick[0].n_x;
const n_y_eye = a_o_stick[0].n_y;

function f_o_p(n_it_layer_nor, n_it_corner_nor) {
    const n_z = n_it_layer_nor * n_height;
    const n_angle = n_it_corner_nor * n_tau;
    const n_dx = sin(n_angle);
    const n_dy = cos(n_angle);

    // Take the farthest point of any stick in this direction.
    let n_r = 0.8;
    for (const o of a_o_stick) {
        // 1 on the straight part, down to 0 at the tip.
        const n_s = clamp((o.n_h - n_z) / o.n_tip, 0, 1);
        if (n_s <= 0) continue;
        // Where the line of sight enters and leaves the six sides.
        // In the pyramid they close in on the tip's place.
        let n_t_in = 0;
        let n_t_out = 1e9;
        for (const o_side of o.a_o_side) {
            const n_speed = o_side.n_nx * n_dx + o_side.n_ny * n_dy;
            const n_left = o_side.n_dist * n_s
                - (o_side.n_nx * (n_x_eye - o.n_x_tip)
                    + o_side.n_ny * (n_y_eye - o.n_y_tip));
            if (n_speed > 1e-9) {
                n_t_out = min(n_t_out, n_left / n_speed);
            } else if (n_speed < -1e-9) {
                n_t_in = max(n_t_in, n_left / n_speed);
            } else if (n_left < 0) {
                n_t_out = -1;
            }
        }
        if (n_t_out > n_t_in) n_r = max(n_r, n_t_out);
    }

    return {
        n_x: n_x_eye + n_dx * n_r,
        n_y: n_y_eye + n_dy * n_r,
        n_z: o_thread.n_z + n_height_cone + n_z,
    };
}

return {
    n_its_layer, n_its_corner, f_o_p,
};
